mapper.select:
select
from act_announcement, activity where act_announcement.activity_num = activity.activity_num and act_announcement.actannouncement_isdeleted = 0 and activity.activity_isdeleted = 0 and act_announcement.organization_num = #{organizationNum,jdbcType=INTEGER}
and act_announcement.activity_num = #{activityNum,jdbcType=INTEGER}
order by act_announcement.actannouncement_num desc
